import{_ as s,o as a,c as o,a2 as n}from"./chunks/framework.Boholvbs.js";const E=JSON.parse('{"title":"xsync-ssh(1)","description":"Choose a shell, prepare the remote helper, and bound idle connections.","frontmatter":{"title":"xsync-ssh(1)","description":"Choose a shell, prepare the remote helper, and bound idle connections.","manual":"xsync-ssh(1)","manualName":"SSH & remote helpers","sectionNumber":"1"},"headers":[],"relativePath":"ssh.md","filePath":"ssh.md"}'),t={name:"ssh.md"};function l(c,e,r,p,i,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="xsync-ssh-1" tabindex="-1">xsync-ssh(1) <a class="header-anchor" href="#xsync-ssh-1" aria-label="Permalink to &quot;xsync-ssh(1)&quot;">​</a></h1><div class="manual-deck"><strong>SSH &amp; remote helpers</strong><p>Choose a shell, prepare the remote helper, and bound idle connections.</p></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION {#description}&quot;">​</a></h2><p>xsync transports its native protocol over a remote shell, normally OpenSSH. Paths are carried as protocol data. The helper must support the client’s protocol and requested capabilities.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES {#examples}&quot;">​</a></h2><div class="example-caption">Use a specific SSH identity</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xsync </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> -e</span><span style="color:#DEDEDE;"> &quot;ssh -i ~/.ssh/backup_key&quot;</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@host:/backup/</span></span></code></pre></div><div class="example-caption">Use a different SSH port</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xsync </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> -e</span><span style="color:#DEDEDE;"> &quot;ssh -p 2222&quot;</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@host:/backup/</span></span></code></pre></div><div class="example-caption">Bracketed IPv6 host</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xsync </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> &quot;user@[::1]:backup/&quot;</span></span></code></pre></div><p>An empty remote path, <code>host:</code>, refers to the remote current directory. Leading <code>~</code> and <code>~user</code> expand on the server; quote remote wildcards to prevent your local shell from expanding them.</p><h2 id="helper" tabindex="-1">HELPER LOOKUP <a class="header-anchor" href="#helper" aria-label="Permalink to &quot;HELPER LOOKUP {#helper}&quot;">​</a></h2><p>Transfers try <code>xsync</code> on remote PATH, then <code>~/.local/bin/xsync</code>, then <code>XSYNC_REMOTE_PATH</code>. The local environment value takes precedence over the remote value.</p><div class="example-caption">Choose an explicit helper</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xsync </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> --rsync-path=/opt/bin/xsync</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@host:/backup/</span></span></code></pre></div><aside class="manual-note"><span>NOTE</span><p>An explicit <code>--rsync-path</code> bypasses automatic lookup. If fallback is needed, that same command must support rsync. An explicit xsync-only executable may therefore prevent fallback.</p></aside><h2 id="install" tabindex="-1">EXPLICIT REMOTE INSTALL <a class="header-anchor" href="#install" aria-label="Permalink to &quot;EXPLICIT REMOTE INSTALL {#install}&quot;">​</a></h2><div class="example-caption">Install the matching release at ~/.local/bin/xsync</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xsync </span><span style="color:#DEDEDE;">--install</span><span style="color:#DEDEDE;"> user@host</span></span></code></pre></div><p>The install command probes the remote OS and architecture and chooses the matching release artifact. Existing newer or unrecognized versions are refused unless <code>--force</code> is given. This requires matching release binaries to be available locally.</p><aside class="manual-note"><span>NOTE</span><p>Starting a transfer never uploads or silently installs a helper.</p></aside><h2 id="limits" tabindex="-1">BANDWIDTH AND TIMEOUTS <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;BANDWIDTH AND TIMEOUTS {#limits}&quot;">​</a></h2><div class="example-caption">Limit bandwidth and remote idle time</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xsync </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> --bwlimit=10M</span><span style="color:#DEDEDE;"> --timeout=60</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@host:/backup/</span></span></code></pre></div><p>Bare bandwidth numbers are KiB/s. Suffixed rates accept binary and decimal units; <code>0</code> disables the limit. Compression limits serialized wire bytes remotely; local workers share a limit on bytes written.</p><p><code>--timeout</code> bounds remote idle I/O, including shell/hello waits, partial frames, blocked writes, and a helper that remains alive after protocol EOF. <code>0</code> disables it. Local copies have no remote I/O deadline. A timeout exits with code <code>30</code>.</p><h2 id="protocol" tabindex="-1">PROTOCOL AND FALLBACK <a class="header-anchor" href="#protocol" aria-label="Permalink to &quot;PROTOCOL AND FALLBACK {#protocol}&quot;">​</a></h2><p>Protocol 4 supports protocols 4 and 3. Optional features are negotiated before use. Missing helper support, incompatible protocols, and unsupported flags can delegate to rsync before transfer. <code>--no-fallback</code> fails instead.</p><p>See <a href="compatibility.html">compatibility</a> for fallback boundaries and <a href="environment.html">environment</a> for remote-shell precedence.</p>',30)])])}const D=s(t,[["render",l]]);export{E as __pageData,D as default};
